import fitz
import re
from pathlib import Path

patterns = {
    'email': re.compile(r'\S+@\S+'),
    'arxiv': re.compile(r'arxiv', re.I),
    'doi': re.compile(r'\b10\.\d{4,9}/\S+|\bdoi\b', re.I),
    'affil': re.compile(r'\b(University|Institute|Laboratory|College|Inc\.|Ltd\.|LLC|Corporation|Corp\.|Company|School|Department|Adobe|Duke|Carnegie|Cornell|Renmin|Georgia|Kumshan|Kunshan)\b'),
    'venue': re.compile(r'\b(Conference|Workshop|Proceedings|ICML|NeurIPS|ACL|EMNLP|NAACL|ICLR|ICASSP|Interspeech|AAAI|CVPR|ECCV|ICCV|SIGGRAPH|KDD|WWW|CHI|IJCAI|COLING|EACL|NIPS|AAAI|Accepted|Published)\b', re.I),
}

for i in range(1,4):
    path = Path(f"/root/paper{i}.pdf")
    doc = fitz.open(path)
    ref_idx = None
    for idx, page in enumerate(doc):
        if 'references' in page.get_text().lower():
            ref_idx = idx
            break
    print(f"=== {path} (ref idx {ref_idx}) ===")
    for page_num, page in enumerate(doc):
        if ref_idx is not None and page_num >= ref_idx:
            break
        text = page.get_text()
        lines = [l.strip() for l in text.splitlines() if l.strip()]
        for l in lines:
            hit = False
            for name, pat in patterns.items():
                if pat.search(l):
                    hit = True
                    break
            if hit:
                print(f"p{page_num+1}: {l}")
    doc.close()
